package com.mis.mis_backend.subject;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/subjects") public class SubjectController{private final SubjectService s;public SubjectController(SubjectService s){this.s=s;}@GetMapping public List<Subject> getAllSubjects(){return s.getAllSubjects();}@PostMapping public Subject createSubject(@RequestBody Subject x){return s.createSubject(x);}}